 # ADR-002: Electron 作为桌面端壳

 ## 元数据

 - **状态**: 已接受
 - **日期**: 2026-09-19
 - **影响范围**: 桌面端（macOS、Windows、Linux）

 ---

 ## 决策

 使用 Electron 作为桌面端壳。

 ---

 ## 架构设计

 ```
 ┌─────────────────────────────────────────┐
 │  渲染进程（插件 UI）                     │
 │  - React + fork antd                    │
 │  - 渲染在 Chromium 中                    │
 │  - 通过 Bridge 调用能力                  │
 └─────────────────────────────────────────┘
                     ↕
               contextBridge
                     ↕
 ┌─────────────────────────────────────────┐
 │  主进程                                  │
 │  - Cordis 运行时（Rust via Neon）       │
 │  - Bridge 实现                           │
 │  - 插件加载器                            │
 │  - Node.js + Rust Native Module         │
 └─────────────────────────────────────────┘
                     ↕
 ┌─────────────────────────────────────────┐
 │  Electron                                │
 │  - Chromium 渲染引擎                     │
 │  - Node.js 运行时                        │
 │  - 系统 API 封装                         │
 └─────────────────────────────────────────┘
 ```

 ---

 ## 版本要求

 - Electron >= 27.x
 - Chromium >= 118
 - Node.js >= 18 LTS

 ---

 ## 进程模型

 ### 主进程

 ```typescript
 // main.ts
 import { app, BrowserWindow } from 'electron';
 import { initCordis } from './cordis';
 import { initBridge } from './bridge';

 app.on('ready', async () => {
   // 初始化 Cordis（Rust 实现）
   await initCordis();

   // 初始化 Bridge
   await initBridge();

   // 创建窗口
   const win = new BrowserWindow({
     width: 1200,
     height: 800,
     webPreferences: {
       nodeIntegration: false,
       contextIsolation: true,
+      sandbox: true,
       preload: path.join(__dirname, 'preload.js'),
     },
   });

   win.loadFile('index.html');
 });
 ```

 ### 预加载脚本

 ```typescript
 // preload.ts
 import { contextBridge, ipcRenderer } from 'electron';
+import type { IResourceHandle, ISubscription } from '@chips/sdk';
+import { createResourceHandle } from './bridge/resource-handle';

-// 暴露 Bridge API
+// 暴露 Bridge API：window.chips 与 IChipsBridge 同形状（R2）
 contextBridge.exposeInMainWorld('chips', {
-  // 能力请求
-  request: async (capabilityId: string) => {
-    return ipcRenderer.invoke('bridge:request', capabilityId);
-  },
+  // 能力请求：输入随请求携带，返回能力执行结果
+  request: (capabilityId: string, input?: unknown): Promise<unknown> =>
+    ipcRenderer.invoke('bridge:request', capabilityId, input),

-  // 事件订阅
-  subscribe: (eventId: string, handler: Function) => {
-    ipcRenderer.on(`event:${eventId}`, (_, data) => handler(data));
+  // 事件订阅：返回可退订句柄
+  subscribe: (eventId: string, handler: (payload: unknown) => void): ISubscription => {
+    const listener = (_event: unknown, payload: unknown): void => handler(payload);
+    ipcRenderer.on(`event:${eventId}`, listener);
+    return {
+      dispose: (): void => {
+        ipcRenderer.removeListener(`event:${eventId}`, listener);
+      },
+    };
   },

-  // 资源访问
-  resource: (uri: string) => {
-    return ipcRenderer.invoke('bridge:resource', uri);
-  },
+  // 资源访问：返回资源句柄
+  resource: (uri: string): IResourceHandle => createResourceHandle(uri),
 });
 ```

 ### 渲染进程

 ```typescript
 // renderer/index.tsx
 import React from 'react';
 import { createRoot } from 'react-dom/client';
 import { App } from './App';

 // 使用 window.chips（由 preload.ts 注入）
 const bridge = window.chips;

 const root = createRoot(document.getElementById('root')!);
 root.render(<App bridge={bridge} />);
 ```

 ---

 ## IPC 通信

 ### 主进程 → 渲染进程

 ```typescript
 // 主进程
 win.webContents.send('plugin:loaded', { id: 'plugin-001' });

 // 渲染进程
-window.chips.subscribe('plugin:loaded', (data) => {
-  console.log('Plugin loaded:', data.id);
+window.chips.subscribe('plugin:loaded', (payload) => {
+  console.log('Plugin loaded:', payload);
 });
 ```

 ### 渲染进程 → 主进程

 ```typescript
 // 渲染进程
-const result = await window.chips.request('file:read');
+const content = await window.chips.request<string>('file:read', { path: 'resources/photo.jpg' });

 // 主进程
-ipcMain.handle('bridge:request', async (event, capabilityId) => {
-  const capability = await bridge.request(capabilityId);
-  return capability;
+ipcMain.handle('bridge:request', async (_event, capabilityId: string, input?: unknown) => {
+  return bridge.request(capabilityId, input);
 });
 ```

