 ## 安全配置

 ### webPreferences 配置

 ```typescript
 webPreferences: {
   // 禁用 Node.js 集成（安全）
   nodeIntegration: false,

   // 启用上下文隔离（安全）
   contextIsolation: true,

-  // 禁用远程模块
-  enableRemoteModule: false,
-  
   // 启用沙箱
   sandbox: true,

   // 预加载脚本
   preload: path.join(__dirname, 'preload.js'),

-  // 禁用 webSecurity（仅开发环境）
-  webSecurity: process.env.NODE_ENV === 'production',
+  // 保持 webSecurity 启用（生产环境禁止关闭）
+  webSecurity: true,
 }
 ```

 ### CSP 策略

 ```html
 <!-- index.html -->
 <meta http-equiv="Content-Security-Policy" 
       content="
         default-src 'self';
         script-src 'self';
         style-src 'self' 'unsafe-inline';
         img-src 'self' data: chips-resource:;
       ">
 ```

 ---

 ## 自定义协议

 ### 注册协议

 ```typescript
 // 主进程
 import { protocol } from 'electron';

 app.whenReady().then(() => {
   // 注册 chips-resource:// 协议
   protocol.registerFileProtocol('chips-resource', (request, callback) => {
     const url = request.url.replace('chips-resource://', '');
     const filePath = resolveResourcePath(url);
     callback({ path: filePath });
   });
 });
 ```

 ### 使用协议

 ```html
 <!-- 渲染进程 -->
 <img src="chips-resource://card-001/image.jpg" />
 ```

 ---

 ## 窗口管理

 ### 创建窗口

 ```typescript
 import { BrowserWindow } from 'electron';

 function createWindow(options: WindowOptions): BrowserWindow {
   const win = new BrowserWindow({
     width: options.width || 1200,
     height: options.height || 800,
     title: options.title,
     webPreferences: {
       nodeIntegration: false,
       contextIsolation: true,
+      sandbox: true,
       preload: PRELOAD_PATH,
     },
   });

   win.loadURL(options.url);
   return win;
 }
 ```

 ### 窗口通信

 ```typescript
 // 主窗口 → 子窗口
 childWindow.webContents.send('message', data);

 // 子窗口 → 主窗口
 parentWindow.webContents.send('message', data);
 ```

 ---

 ## 原生模块集成

 ### Neon 绑定

 ```rust
 // native/src/lib.rs
 use neon::prelude::*;

 // Rust 函数
 fn parse_card(path: &str) -> Result<Card> {
     // Rust 实现
 }

 // 导出到 Node.js
 fn js_parse_card(mut cx: FunctionContext) -> JsResult<JsObject> {
     let path = cx.argument::<JsString>(0)?.value(&mut cx);
     let card = parse_card(&path).or_else(|e| cx.throw_error(e.to_string()))?;

     let obj = cx.empty_object();
     // 填充对象...
     Ok(obj)
 }

 #[neon::main]
 fn main(mut cx: ModuleContext) -> NeonResult<()> {
     cx.export_function("parseCard", js_parse_card)?;
     Ok(())
 }
 ```

 ### Node.js 调用

 ```typescript
 // 主进程
 import { parseCard } from '../native';

 const card = parseCard('/path/to/card.card');
 ```

