 ## 接口定义

 ### Bridge 核心接口

 ```typescript
 interface IChipsBridge {
-  // 请求能力
-  request<T extends ICapability>(id: string): Promise<T>;
+  // 请求能力：输入随请求携带，返回执行结果
+  request<TOutput>(capabilityId: string, input?: unknown): Promise<TOutput>;

-  // 订阅事件
-  subscribe<E>(eventId: string, handler: (event: E) => void): ISubscription;
+  // 订阅事件：返回可退订句柄
+  subscribe(eventId: string, handler: (payload: unknown) => void): ISubscription;

   // 资源访问
