 ## 类型系统

 ### 能力类型定义

 ```typescript
 // file:read 能力
 interface IFileReadCapability extends ICapability<
   { path: string; encoding?: string },
   string
 > {
   id: 'file:read';
 }

 // image:decode 能力
 interface IImageDecodeCapability extends ICapability<
   { data: Buffer; format?: string },
   IImageData
 > {
   id: 'image:decode';
 }

 // window:create 能力
 interface IWindowCreateCapability extends ICapability<
   { width: number; height: number; title: string },
   IWindow
 > {
   id: 'window:create';
 }
 ```

 ### 使用示例

 ```typescript
 // 插件代码（类型安全：以执行结果为泛型参数）
 async function readAndDecode(imagePath: string): Promise<IImageData> {
   // 请求能力（返回类型明确）
   const data = await chips.request<string>('file:read', { path: imagePath });
   const image = await chips.request<IImageData>('image:decode', {
     data: Buffer.from(data),
   });

   return image;
 }
 ```

 ---

 ## 权限系统

 ### 权限声明

 ```yaml
 # manifest.yaml
 id: chips.plugin.image-editor
 permissions:
   - filesystem:read      # 文件系统读取
   - filesystem:write     # 文件系统写入
   - image:process        # 图像处理（解码/编码/缩放等）
 ```

 ### 权限检查

 ```typescript
 // Bridge 在调用时自动判定：插件缺少 filesystem:read 权限则拒绝
-await bridge.request<string>('file:read', { path: 'resources/file.txt' });
-// 拒绝时返回错误码 PERMISSION_DENIED
+await bridge.request<string>('file:read', { path: 'file.txt' });
+// 拒绝时返回错误码 BRIDGE_PERMISSION_DENIED
 ```

 ### 权限粒度

 ```typescript
 // 细粒度权限（qualifier 限定作用范围）
 filesystem:read:documents        // 只能读取文档目录
 filesystem:write:temp            // 只能写入临时目录
 network:http:*.example.com       // 只能访问特定域名
 ```

 ---

 ## 参数验证

 ### JSON Schema 验证

 ```typescript
 // 能力定义
 const fileReadCapability = {
   id: 'file:read',
   schema: {
     input: {
       type: 'object',
       properties: {
         path: { type: 'string', minLength: 1 },
         encoding: { 
           type: 'string', 
           enum: ['utf-8', 'ascii', 'base64'],
           default: 'utf-8',
         },
       },
       required: ['path'],
     },
     output: {
       type: 'string',
     },
   },
   execute: async (input: { path: string; encoding?: string }) => {
     return fs.readFileSync(input.path, input.encoding);
   },
 };

 // Bridge 自动验证
-await chips.request('file:read', { path: '' });                     // ❌ 错误：path 长度不足
-await chips.request('file:read', { path: 'resources/file.txt' });   // ✅ 正确
+await chips.request('file:read', { path: '' });  // ❌ 错误：path 长度不足
+await chips.request('file:read', { path: 'file.txt' });  // ✅ 正确
 await chips.request('file:read', {
-  path: 'resources/file.txt',
+  path: 'file.txt',
   encoding: 'invalid',
 });  // ❌ 错误：encoding 不在枚举中
 ```

