 ## 能力组合

 ### 链式调用

 ```typescript
 async function processImage(path: string): Promise<void> {
   // 链式处理：request 携带输入并返回输出
   const data = await chips.request<string>('file:read', { path });
   const image = await chips.request<IImageData>('image:decode', { data: Buffer.from(data) });
   const resized = await chips.request<IImageData>('image:resize', {
     image,
     width: 800,
     height: 600,
   });
   const encoded = await chips.request<Blob>('image:encode:jpeg', {
     image: resized,
     quality: 90,
   });
   await chips.request('file:write', { path: 'output.jpg', data: encoded });
 }
 ```

 ### 高阶能力

 ```typescript
 // 插件可以提供新能力
 class ImageFilterPlugin {
   constructor(ctx: Context) {
     // 注册新能力：能力声明自己需要的权限（R3）
     ctx.bridge.register('image:filter:blur', {
       id: 'image:filter:blur',
       permissions: ['image:process'],
       execute: async (input: { data: string; radius: number }) => {
         // 组合基础能力实现新能力
         const image = await ctx.bridge.request<IImageData>('image:decode', {
           data: Buffer.from(input.data),
         });
         const blurred = applyBlur(image, input.radius);
         return ctx.bridge.request<Blob>('image:encode', { image: blurred });
       },
     });
   }
 }
 ```

