   'file:read': {
     type: 'object',
     additionalProperties: false,
     required: ['path'],
     properties: {
       path: { type: 'string', minLength: 1 },
       encoding: { type: 'string', enum: ['utf-8', 'base64'], default: 'utf-8' },
     },
   },
   'file:list': {
     type: 'object',
     additionalProperties: false,
     required: ['directory'],
     properties: {
       directory: { type: 'string', minLength: 1 },
       recursive: { type: 'boolean', default: false },
     },
   },
   'file:watch': {
     type: 'object',
     additionalProperties: false,
     required: ['path'],
     properties: {
       path: { type: 'string', minLength: 1 },
       recursive: { type: 'boolean', default: false },
     },
   },
   'file:write': {
     type: 'object',
     additionalProperties: false,
     required: ['path', 'data'],
     properties: {
       path: { type: 'string', minLength: 1 },
       data: { type: 'string' },
