 ```typescript
 // hooks.ts
 export function useCardData(cardId: string) {
   const [data, setData] = useState<Card | null>(null);
   const [loading, setLoading] = useState(true);
   const [error, setError] = useState<Error | null>(null);

   useEffect(() => {
     let cancelled = false;

     setLoading(true);
     loadCard(cardId)
       .then(card => {
         if (!cancelled) {
           setData(card);
           setLoading(false);
         }
       })
       .catch(err => {
         if (!cancelled) {
           setError(err);
           setLoading(false);
         }
       });

     return () => {
       cancelled = true;
     };
   }, [cardId]);

   return { data, loading, error };
 }

 // 使用
 const { data, loading, error } = useCardData(cardId);
 ```

