+
+<script>
+const $ = (s, r = document) => r.querySelector(s);
+const $$ = (s, r = document) => [...r.querySelectorAll(s)];
+const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
+const api = async (p, q = {}) => {
+  const u = new URL(p, location.origin);
+  Object.entries(q).forEach(([k, v]) => { if (v !== "" && v != null) u.searchParams.set(k, v); });
+  const r = await fetch(u);
+  if (!r.ok) throw new Error((await r.json()).error || r.status);
+  return r.json();
+};
+const badge = s => `<span class="badge s-${esc(s)}">${esc(s)}</span>`;
+const bar = arr => `<div class="bar">${arr.map(x => x.n ? `<i class="seg-${esc(x.status)}" style="width:${x.pct}%" title="${esc(x.status)} ${x.n}"></i>` : "").join("")}</div>`;
+
+let stats = null;
+const state = {
+  view: "overview",
+  gaps: { page: 0, limit: 50, severity: "", status: "open", source: "", q: "" },
+  nodes: { page: 0, limit: 50, status: "", dimension: "", source: "", q: "" },
+};
+
+function stack(rows, keyOf) {
+  const map = new Map();
+  rows.forEach(r => {
+    const k = keyOf(r);
+    if (!map.has(k)) map.set(k, { key: k, total: 0, parts: {} });
+    const e = map.get(k);
+    e.total += r.n; e.parts[r.status] = (e.parts[r.status] || 0) + r.n;
+  });
+  return [...map.values()].sort((a, b) => b.total - a.total);
+}
+
+function renderOverview() {
+  const by = Object.fromEntries(stats.by_status.map(r => [r.k, r.n]));
+  const total = Object.values(by).reduce((a, b) => a + b, 0) || 1;
+  const gapP1 = stats.gaps.filter(g => g.severity === "P1" && g.status === "open").reduce((a, b) => a + b.n, 0);
+  const gapP2 = stats.gaps.filter(g => g.severity === "P2" && g.status === "open").reduce((a, b) => a + b.n, 0);
+  const order = stats.status_order;
+  const segs = order.map(s => ({ status: s, n: by[s] || 0, pct: Math.round((by[s] || 0) / total * 1000) / 10 }));
+  $("#view-overview").innerHTML = `
+    <div class="cards">
+      <div class="card"><div class="num">${total}</div><div class="lbl">节点总数</div></div>
+      <div class="card"><div class="num" style="color:var(--ok)">${by["已覆盖"] || 0}</div><div class="lbl">已覆盖</div></div>
+      <div class="card"><div class="num" style="color:var(--part)">${by["部分"] || 0}</div><div class="lbl">部分覆盖</div></div>
+      <div class="card"><div class="num" style="color:var(--miss)">${by["缺失"] || 0}</div><div class="lbl">缺失</div></div>
+      <div class="card"><div class="num" style="color:var(--conf)">${by["冲突"] || 0}</div><div class="lbl">冲突</div></div>
+      <div class="card"><div class="num" style="color:var(--miss)">${gapP1}</div><div class="lbl">未闭合 P1 缺口</div></div>
+      <div class="card"><div class="num" style="color:var(--part)">${gapP2}</div><div class="lbl">未闭合 P2 缺口</div></div>
+      <div class="card"><div class="num">${stats.docs}</div><div class="lbl">新文档登记</div></div>
+      <div class="card"><div class="num">${stats.edges}</div><div class="lbl">关系边</div></div>
+    </div>
+    <div class="panel">
+      <h2>覆盖进度</h2>
+      <div class="progress">${segs.map(s => s.n ? `<i class="seg-${s.status}" style="width:${s.pct}%" title="${s.status} ${s.n}"></i>` : "").join("")}</div>
+      <div class="legend">${segs.filter(s => s.n).map(s => `<span><i class="dot" style="background:var(--${({ "已覆盖": "ok", "部分": "part", "缺失": "miss", "冲突": "conf" })[s.status] || "alt"})"></i>${s.status} ${s.n}</span>`).join("")}</div>
+    </div>
+    <div class="panel"><h2>覆盖状态分布</h2>
+      <table><thead><tr><th>状态</th><th>数量</th><th style="width:60%">占比</th></tr></thead><tbody>
+      ${order.filter(s => by[s]).map(s => `<tr><td>${badge(s)}</td><td>${by[s]}</td>
+        <td><div class="bar"><i class="seg-${s}" style="width:${Math.round(by[s] / total * 100)}%"></i></div></td></tr>`).join("")}
+      </tbody></table>
+    </div>
+    <div class="panel"><h2>缺口（按严重度 / 状态）</h2>
+      <table><thead><tr><th>严重度</th><th>状态</th><th>数量</th></tr></thead><tbody>
+      ${stats.gaps.map(g => `<tr><td>${esc(g.severity)}</td><td>${badge(g.status)}</td><td>${g.n}</td></tr>`).join("")}
+      </tbody></table>
+    </div>`;
+}
+
+function renderSources() {
+  const groups = stack(stats.by_source, r => r.source);
+  $("#view-sources").innerHTML = `<div class="panel"><h2>来源覆盖（旧文档库 / 旧仓库 / 新库）</h2>
+    <table><thead><tr><th>来源</th><th>总计</th><th style="width:40%">分布</th>
+    ${stats.status_order.map(s => `<th class="heat">${s}</th>`).join("")}</tr></thead><tbody>
+    ${groups.map(g => `<tr><td class="wrap">${esc(g.key)}</td><td>${g.total}</td>
+      <td>${bar(stats.status_order.map(s => ({ status: s, n: g.parts[s] || 0, pct: Math.round((g.parts[s] || 0) / g.total * 100) })))}</td>
+      ${stats.status_order.map(s => `<td class="heat">${g.parts[s] || ""}</td>`).join("")}</tr>`).join("")}
+    </tbody></table></div>`;
+}
+
+function renderDims() {
+  const dims = stats.dimensions.filter(d => d !== "其他");
+  const cell = (d, s) => stats.by_dimension.find(r => r.dimension === d && r.status === s)?.n || 0;
+  const heat = n => n === 0 ? "heat-0" : n < 5 ? "heat-1" : n < 20 ? "heat-2" : "heat-3";
+  $("#view-dims").innerHTML = `<div class="panel"><h2>维度 × 状态矩阵</h2>
+    <table><thead><tr><th>维度</th>${stats.status_order.map(s => `<th class="heat">${s}</th>`).join("")}<th>合计</th></tr></thead><tbody>
+    ${dims.map(d => {
+      const cells = stats.status_order.map(s => cell(d, s));
+      return `<tr><td>${esc(d)}</td>${cells.map(n => `<td class="heat ${heat(n)}">${n || ""}</td>`).join("")}
+        <td class="heat">${cells.reduce((a, b) => a + b, 0)}</td></tr>`;
+    }).join("")}
+    </tbody></table></div>`;
+}
+
+async function renderGaps() {
+  const st = state.gaps;
+  const r = await api("/api/gaps", { severity: st.severity, status: st.status, source: st.source, q: st.q, limit: st.limit, offset: st.page * st.limit });
+  const pages = Math.ceil(r.total / st.limit);
+  $("#view-gaps").innerHTML = `<div class="panel">
+    <div class="row" style="margin-bottom:10px">
+      <select id="gSeverity"><option value="">全部严重度</option>${stats.severity_order.map(s => `<option ${st.severity === s ? "selected" : ""}>${s}</option>`).join("")}</select>
+      <select id="gStatus">
+        <option value="">全部状态</option>
+        <option value="open" ${st.status === "open" ? "selected" : ""}>未闭合</option>
+        <option value="done" ${st.status === "done" ? "selected" : ""}>已解决</option>
+        <option value="planned" ${st.status === "planned" ? "selected" : ""}>已计划</option>
+        <option value="wontfix" ${st.status === "wontfix" ? "selected" : ""}>不处理</option>
+      </select>
+      <select id="gSource"><option value="">全部来源</option>${stats.sources.map(s => `<option ${st.source === s ? "selected" : ""}>${s}</option>`).join("")}</select>
+      <input id="gQ" placeholder="搜索主题/证据/建议" value="${esc(st.q)}" style="flex:1;min-width:200px">
+      <button id="gApply" class="primary">应用</button>
+      <span class="muted">共 ${r.total} 条</span>
+    </div>
+    <table><thead><tr><th>缺口</th><th>主题</th><th>严重度</th><th>状态</th><th>来源</th><th>证据</th></tr></thead><tbody>
+    ${r.items.map(g => `<tr data-gap="${esc(g.id)}" style="cursor:pointer">
+      <td class="kw">${esc(g.id)}</td><td>${esc(g.topic)}</td><td>${esc(g.severity)}</td>
+      <td>${badge(g.status)}</td><td class="wrap">${esc(g.source_type || "")}</td>
+      <td class="wrap kw">${esc(g.evidence || "").slice(0, 110)}</td></tr>`).join("")}
+    </tbody></table>
+    <div class="pager"><button id="gPrev" ${st.page === 0 ? "disabled" : ""}>上一页</button>
+      <span class="muted">${st.page + 1} / ${pages || 1}</span>
+      <button id="gNext" ${st.page + 1 >= pages ? "disabled" : ""}>下一页</button></div></div>`;
+  $("#gApply").onclick = () => { Object.assign(st, { severity: $("#gSeverity").value, status: $("#gStatus").value, source: $("#gSource").value, q: $("#gQ").value, page: 0 }); renderGaps(); };
+  $("#gPrev").onclick = () => { st.page--; renderGaps(); };
+  $("#gNext").onclick = () => { st.page++; renderGaps(); };
+  $$("#view-gaps tr[data-gap]").forEach(tr => tr.onclick = () => showGapDetail(tr.dataset.gap));
+}
+
+async function showGapDetail(id) {
+  const r = await api("/api/gaps", { q: id, limit: 5 });
+  const g = r.items.find(x => x.id === id);
+  if (!g) return;
+  $("#detail").innerHTML = `<button id="closeDetail" style="float:right">关闭</button>
+    <h3>${esc(g.id)} · ${esc(g.topic)}</h3>
+    <div>${badge(g.status)} <span class="badge s-${g.severity === "P1" ? "缺失" : "部分"}">${esc(g.severity)}</span></div>
+    <dl>
+      <dt>来源</dt><dd>${esc(g.source_type || "")}</dd>
+      <dt>维度</dt><dd>${esc(g.dimensions || "")}</dd>
+      <dt>证据</dt><dd class="kw">${esc(g.evidence || "")}</dd>
+      <dt>建议动作</dt><dd>${esc(g.proposal || g.action || "")}</dd>
+      <dt>处理文档</dt><dd class="kw">${esc(g.doc_path || "")}</dd>
+      <dt>负责人</dt><dd>${esc(g.owner || "")}</dd>
+    </dl>`;
+  $("#detail").classList.add("open");
+  $("#closeDetail").onclick = () => $("#detail").classList.remove("open");
+}
+
+async function renderNodes() {
+  const st = state.nodes;
+  const r = await api("/api/nodes", { status: st.status, dimension: st.dimension, source: st.source, q: st.q, limit: st.limit, offset: st.page * st.limit });
+  const pages = Math.ceil(r.total / st.limit);
