+    // 检测围栏代码块（``` 或 ~~~）
+    const fenceMatch = line.match(/^(\s*)(`{3,}|~{3,})/);
+    if (fenceMatch) {
+      const marker = fenceMatch[2][0];
+      if (!inFence) {
+        inFence = true;
+        fenceMarker = marker;
+      } else if (marker === fenceMarker) {
+        inFence = false;
+        fenceMarker = null;
+      }
+      continue;
+    }
+    if (inFence) continue;
+    // 仅匹配顶层 H2：行首 ## 开头且不是 ###
+    if (/^##\s+\S/.test(line) && !/^###\s/.test(line)) {
+      indices.push(i);
+    }
+  }
+  return indices;
+}
+
+/**
+ * 在文档行数组中找出所有 H3 标题（### 开头）的位置（不含代码块）
+ */
+function findH3Indices(lines) {
+  const indices = [];
+  let inFence = false;
+  let fenceMarker = null;
+  for (let i = 0; i < lines.length; i++) {
+    const line = lines[i];
+    const fenceMatch = line.match(/^(\s*)(`{3,}|~{3,})/);
+    if (fenceMatch) {
+      const marker = fenceMatch[2][0];
+      if (!inFence) {
+        inFence = true;
+        fenceMarker = marker;
+      } else if (marker === fenceMarker) {
+        inFence = false;
+        fenceMarker = null;
+      }
+      continue;
+    }
+    if (inFence) continue;
+    if (/^###\s+\S/.test(line)) {
+      indices.push(i);
+    }
+  }
+  return indices;
