+function extractFrontMatter(lines) {
+  let i = 0;
+  // 跳过前导空行
+  while (i < lines.length && lines[i].trim() === '') i++;
+  // 读 H1 标题
+  let title = '';
+  if (i < lines.length) {
+    const m = lines[i].match(/^#\s+(.+?)\s*$/);
+    if (m) {
+      title = m[1];
+      i++;
+    }
+  }
+  // 跳过标题后的空行
+  while (i < lines.length && lines[i].trim() === '') i++;
+
