+  // 跳过分隔线和空行，找到第一个 H2
+  while (i < lines.length) {
+    const line = lines[i];
+    if (/^---+$/.test(line.trim()) || line.trim() === '') {
+      i++;
+      continue;
+    }
+    if (/^##\s+/.test(line)) break;
+    i++;
+  }
