-}
-```
-
-### 2.2 默认值
-
-```typescript
-// 使用解构默认值
-export const Component: React.FC<Props> = ({
-  disabled = false,
-  size = 'medium',
-  ...rest
-}) => {
-  // ...
-};
-
-// 或使用 defaultProps（旧方式）
-Component.defaultProps = {
-  disabled: false,
-  size: 'medium',
-};
-```
-
 ---

-## 三、Hooks 使用
+拆分说明：本文档保留元数据与章节目录，正文内容位于目录中的章节文档。

-### 3.1 Hooks 顺序
-
-```tsx
-export const Component: React.FC<Props> = (props) => {
-  // 1. useState
-  const [count, setCount] = useState(0);
-  const [text, setText] = useState('');
-
-  // 2. useRef
-  const ref = useRef<HTMLDivElement>(null);
-
-  // 3. Design Tokens（antd 主题经 @chips/ui 暴露）
-  const { token } = theme.useToken();
-
-  // 4. useMemo
-  const computed = useMemo(() => {
-    return expensiveComputation(count);
-  }, [count]);
-
-  // 5. useCallback
-  const handleClick = useCallback(() => {
-    setCount((current) => current + 1);
-  }, []);
-
-  // 6. useEffect
-  useEffect(() => {
-    // Side effect
-  }, [dependencies]);
-
-  // 7. 自定义 Hooks
-  const data = useCustomHook(id);
-
-  // Render
-  return <div style={{ color: token.colorPrimary }}>...</div>;
-};
-```
-
-### 3.2 自定义 Hooks
-
-```typescript
-// hooks.ts
-export function useCardData(cardId: string) {
-  const [data, setData] = useState<Card | null>(null);
-  const [loading, setLoading] = useState(true);
-  const [error, setError] = useState<Error | null>(null);
-  
-  useEffect(() => {
-    let cancelled = false;
-    
-    setLoading(true);
-    loadCard(cardId)
-      .then(card => {
-        if (!cancelled) {
-          setData(card);
-          setLoading(false);
-        }
-      })
-      .catch(err => {
-        if (!cancelled) {
-          setError(err);
-          setLoading(false);
-        }
-      });
-    
-    return () => {
-      cancelled = true;
-    };
-  }, [cardId]);
-  
-  return { data, loading, error };
-}
-
-// 使用
-const { data, loading, error } = useCardData(cardId);
-```
-
----
-
-## 四、状态管理
-
-### 4.1 useState
-
-```typescript
-// 简单状态
-const [count, setCount] = useState(0);
-
-// 对象状态
-const [user, setUser] = useState<User>({
-  name: '',
-  age: 0,
-});
-
-// 更新对象状态
-setUser(prev => ({
-  ...prev,
-  name: 'New Name',
-}));
-
-// 函数式更新
-setCount(prev => prev + 1);
-```
-
-### 4.2 useReducer
-
-```typescript
-// 复杂状态
-interface State {
-  count: number;
-  text: string;
-  loading: boolean;
-}
-
-type Action =
-  | { type: 'increment' }
-  | { type: 'setText'; payload: string }
-  | { type: 'setLoading'; payload: boolean };
-
-function reducer(state: State, action: Action): State {
-  switch (action.type) {
-    case 'increment':
-      return { ...state, count: state.count + 1 };
-    case 'setText':
-      return { ...state, text: action.payload };
-    case 'setLoading':
-      return { ...state, loading: action.payload };
-    default:
-      return state;
-  }
-}
-
-const [state, dispatch] = useReducer(reducer, {
-  count: 0,
-  text: '',
-  loading: false,
-});
-
-dispatch({ type: 'increment' });
-dispatch({ type: 'setText', payload: 'Hello' });
-```
-
----
-
-## 五、性能优化
-
-### 5.1 React.memo
-
-```typescript
-// 使用 memo 避免不必要的重渲染
-export const ExpensiveComponent = React.memo<Props>(({ data }) => {
-  return <div>{/* Expensive render */}</div>;
-});
-
-// 自定义比较函数
-export const Component = React.memo<Props>(
-  ({ id, name }) => {
-    return <div>{name}</div>;
-  },
-  (prevProps, nextProps) => {
-    return prevProps.id === nextProps.id;
-  }
-);
-```
-
-### 5.2 useMemo
-
-```typescript
-// 缓存计算结果
-const sortedList = useMemo(() => {
-  return list.sort((a, b) => a.order - b.order);
-}, [list]);
-
-// 缓存对象
-const options = useMemo(() => ({
-  format: 'json',
-  compress: true,
-}), []);
-```
-
-### 5.3 useCallback
-
-```typescript
-// 缓存函数
-const handleClick = useCallback(() => {
-  console.log('Clicked');
-}, []);
-
-// 带依赖的函数
