+# React 组件开发规范
+
+> 版本：v1.0.0  
+> 日期：2026-09-19  
+> 状态：正式版  
+> 适用范围：所有 React 组件开发（官方前端、`@chips/ui` 共享层与插件界面），含组件结构、Props、Hooks、状态、性能、样式与测试约定
+
+---
+
+## 四、状态管理
+
+### 4.1 useState
+
+```typescript
+// 简单状态
+const [count, setCount] = useState(0);
+
+// 对象状态
+const [user, setUser] = useState<User>({
+  name: '',
+  age: 0,
+});
+
+// 更新对象状态
+setUser(prev => ({
+  ...prev,
+  name: 'New Name',
+}));
+
+// 函数式更新
+setCount(prev => prev + 1);
+```
+
+### 4.2 useReducer
+
+```typescript
+// 复杂状态
+interface State {
+  count: number;
+  text: string;
+  loading: boolean;
+}
+
+type Action =
+  | { type: 'increment' }
+  | { type: 'setText'; payload: string }
+  | { type: 'setLoading'; payload: boolean };
+
+function reducer(state: State, action: Action): State {
+  switch (action.type) {
+    case 'increment':
+      return { ...state, count: state.count + 1 };
+    case 'setText':
+      return { ...state, text: action.payload };
+    case 'setLoading':
+      return { ...state, loading: action.payload };
+    default:
+      return state;
+  }
+}
+
+const [state, dispatch] = useReducer(reducer, {
+  count: 0,
+  text: '',
+  loading: false,
+});
+
+dispatch({ type: 'increment' });
+dispatch({ type: 'setText', payload: 'Hello' });
+```
+
+---
+
+**文档结束**

