-  });
-
-  it('渲染 1000 个条目 < 1s', () => {
-    const start = performance.now();
-    render(<EntryList entries={Array(1000).fill(mockEntry)} />);
-    const duration = performance.now() - start;
-
-    expect(duration).toBeLessThan(1000);
-  });
-});
-```
-
-- 性能阈值以 R18 与各子系统预算为准（打开卡片 < 100ms、打开箱子 < 200ms、冷启动 < 1s 等）；测量使用固定夹具、固定设备，多轮取中位数。
-- 常规性能测试运行于发布构建；debug 构建数据只用于相对比较，不作为门禁结论。
-
----
-
-## 八、测试工具
-
-### 8.1 测试配置
-
-**vitest.config.ts**:
-```typescript
-import { defineConfig } from 'vitest/config';
-
-export default defineConfig({
-  test: {
-    globals: true,
-    environment: 'jsdom',
-    setupFiles: ['./tests/setup.ts'],
-    coverage: {
-      provider: 'v8',
-      reporter: ['text', 'html', 'lcov'],
-      // 阈值按第 10.2 节：普通包 80%，核心与共享层 90%
-      exclude: [
-        'node_modules/',
-        'tests/',
-        '**/*.test.ts',
-        '**/*.test.tsx',
-        '**/*.spec.ts',
-      ],
-    },
-  },
-});
-```
-
-**tests/setup.ts**:
-```typescript
-import '@testing-library/jest-dom';
-
-// 平台调用不使用全局手写 mock：需要 window.chips 的用例
-// 在用例内调用 @chips/sdk/testing 的 installMockBridge() 安装。
-```
-
-### 8.2 测试夹具
-
-```typescript
-// tests/fixtures/documents.ts
-import type { EntryView } from '@chips/sdk';
-
-export const mockEntry: EntryView = {
-  entry_id: 'a1B2c3D4e5',
-  url: './notes.card',
-  enabled: true,
-  displayTitle: '测试条目',
-  order: 0,
-};
-
-export const mockEntryList: readonly EntryView[] = Array.from({ length: 10 }, (_, index) => ({
-  ...mockEntry,
-  entry_id: `entry-${index}`,
-  displayTitle: `测试条目 ${index}`,
-  order: index,
-}));
-```
-
-- 条目模型以 [09-箱子布局插件接口](../05-接口与契约/09-箱子布局插件接口.md) 的 `EntryView` 为准；夹具禁止使用真实用户数据与真实绝对路径。
-- 文档与插件夹具（`.card` / `.box` / `.cpk`）放 `tests/fixtures/`，正常夹具与损坏夹具分目录存放。
-
----
-
-## 九、测试命名
-
-### 9.1 命名规范
-
-```typescript
-// describe: 描述测试组
-describe('CardParser', () => {
-  
-  // it: 描述单个测试
-  it('should parse valid card', () => {
-    // ...
-  });
-  
-  it('should throw on invalid input', () => {
-    // ...
-  });
-  
-  // 嵌套 describe
-  describe('when input is empty', () => {
-    it('should throw error', () => {
-      // ...
-    });
-  });
-});
-```
-
-### 9.2 测试结构
-
-```typescript
-it('should update card title', () => {
-  // Arrange（准备）
-  const card = createCard({ title: 'Old' });
-  
-  // Act（执行）
-  updateTitle(card, 'New');
-  
-  // Assert（断言）
-  expect(card.title).toBe('New');
-});
-```
-
----
-
-## 十、测试覆盖率
-
-### 10.1 生成报告
-
-```bash
-# TypeScript 包（各包标准脚本）
-pnpm test:coverage
-
-# Rust 工作区
-cargo tarpaulin --workspace --out Xml
-```
-
-- 报告写入仓库根 `coverage/`（不入库）；TS 输出 text + html + lcov，Rust 输出 XML，随 CI 流水线工件归档。
-- 全仓聚合命令为根脚本 `pnpm test:coverage`（[01-代码组织规范](./01-代码组织规范.md) §8.1）。
-
-### 10.2 覆盖率要求
-
-```typescript
-// vitest.config.ts（普通包：总体门槛）
-export default defineConfig({
-  test: {
-    coverage: {
-      provider: 'v8',
-      thresholds: {
-        lines: 80,
-        functions: 80,
-        branches: 80,
-        statements: 80,
-      },
-    },
-  },
-});
-```
-
-```typescript
-// packages/ui、packages/bridge 等共享层包的 vitest.config.ts：90% 门槛
-// Rust 核心（chips-* crates）由 cargo-tarpaulin 以同一 90% 口径判定
-export default defineConfig({
-  test: {
-    coverage: {
-      provider: 'v8',
-      thresholds: {
-        lines: 90,
-        functions: 90,
-        branches: 90,
-        statements: 90,
-      },
-    },
-  },
-});
-```
-
-- 口径：总体 > 80%；Rust 核心（`chips-*` crates）与共享层（`@chips/ui`、`@chips/bridge`）> 90%（R18）。
-- 四个统计维度（行、函数、分支、语句）分别判定；核心与共享层按 90%，其余按 80%。
-- 新增代码不得拉低整体覆盖率；覆盖率下降即失败，不设"先合入再补测试"通道。
-
----
-
-## 十一、持续集成
-
-### 11.1 GitHub Actions
-
-```yaml
-# .github/workflows/test.yml
-name: Test
-
-on: [push, pull_request]
-
-jobs:
-  test:
-    runs-on: ubuntu-latest
-
-    steps:
-      - uses: actions/checkout@v4
-
-      - name: Setup pnpm
-        uses: pnpm/action-setup@v4
-
-      - name: Setup Node.js
-        uses: actions/setup-node@v4
-        with:
-          node-version: 18
-          cache: pnpm
-
-      - name: Install dependencies
-        run: pnpm install --frozen-lockfile
-
-      - name: Run tests
-        run: pnpm test
-
-      - name: Run contract tests
-        run: pnpm test:contract
-
-      - name: Run coverage
-        run: pnpm test:coverage
-
-      - name: Upload coverage
-        uses: codecov/codecov-action@v4
-```
-
-- Node 生态唯一包管理器为 pnpm；CI 禁止出现 `npm ci` / `npm install` / `yarn`。
-- 门禁集合、覆盖率与契约门禁的完整判定以 [05-CICD与质量门禁](../06-开发与运维/05-CICD与质量门禁.md) 为准。
-
----
-
-## 十二、强制规则
-
-### 必须遵守
-
-1. 所有公开 API 必须有单元测试
-2. 核心功能必须有集成测试
-3. 关键流程必须有 E2E 测试（Playwright Electron，禁止 localhost 网页形态）
-4. 覆盖率：总体 > 80%，Rust 核心与共享层 > 90%（R18）
-5. 契约测试（帧协议、角色接口快照、插件兼容、迁移工具矩阵）随 `pnpm test:contract` 通过
-6. 所有测试必须通过
-7. 测试不能依赖外部服务（平台调用经 `@chips/sdk/testing` 提供 Mock）
-
-### 禁止行为
-
-```typescript
-// ❌ 禁止跳过测试（除非临时调试）
-it.skip('test', () => {});
-
-// ❌ 禁止依赖测试执行顺序
-// ❌ 禁止测试之间共享状态
-// ❌ 禁止在测试中使用真实的外部 API
-```
-
----
-
 **文档结束**

