+# 测试规范
+
+> 版本：v1.0.0  
+> 日期：2026-09-19  
+> 状态：正式版  
+> 适用范围：全部测试代码：测试策略与覆盖率口径、单元/组件/集成/E2E/性能测试、契约与专项测试、Mock 与测试工具、覆盖率报告与 CI 约定
+
+---
+
+## 三、React 组件测试
+
+### 3.1 渲染测试
+
+```tsx
+import { afterEach, describe, expect, it, vi } from 'vitest';
+import { render, screen } from '@testing-library/react';
+import { installMockBridge } from '@chips/sdk/testing';
+import { CardTile } from './CardTile';
+
+describe('CardTile', () => {
+  const bridge = installMockBridge();
+
+  afterEach(() => {
+    bridge.reset();
+  });
+
+  it('渲染卡片标题', async () => {
+    bridge.handle('document:open', () => ({
+      documentId: 'card-001',
+      source: 'chips-resource://card-001',
+      kind: 'card',
+      title: '测试卡片',
+      digest: 'sha256:0',
+    }));
+
+    render(<CardTile cardId="card-001" />);
+
+    expect(await screen.findByText('测试卡片')).toBeInTheDocument();
+  });
+
+  it('点击触发回调', () => {
+    const onClick = vi.fn();
+    render(<CardTile cardId="card-001" onClick={onClick} />);
+
+    screen.getByRole('button').click();
+    expect(onClick).toHaveBeenCalledOnce();
+  });
+});
+```
+
+- 组件样式来自 `@chips/ui` 与 Design Tokens，测试不得断言具体色值、间距等视觉数值；只断言可访问性角色、文案与交互结果。
+- 组件中的平台调用经 `installMockBridge` 提供，不启动真实平台；具体 Props 以被测组件自身的类型声明为准，示例只演示测试结构。
+
+### 3.2 交互测试
+
+```typescript
+import { render, screen, fireEvent } from '@testing-library/react';
+import userEvent from '@testing-library/user-event';
+
+describe('Button interactions', () => {
+  it('handles click', () => {
+    const handleClick = vi.fn();
+    render(<Button onClick={handleClick}>Click</Button>);
+    
+    fireEvent.click(screen.getByRole('button'));
+    expect(handleClick).toHaveBeenCalledTimes(1);
+  });
+  
+  it('handles keyboard input', async () => {
+    const user = userEvent.setup();
+    render(<Input />);
+    
+    const input = screen.getByRole('textbox');
+    await user.type(input, 'Hello');
+    
+    expect(input).toHaveValue('Hello');
+  });
+  
+  it('handles form submission', async () => {
+    const user = userEvent.setup();
+    const handleSubmit = vi.fn();
+    
+    render(
+      <form onSubmit={handleSubmit}>
+        <input name="username" />
+        <button type="submit">Submit</button>
+      </form>
+    );
+    
+    await user.type(screen.getByRole('textbox'), 'testuser');
+    await user.click(screen.getByRole('button'));
+    
+    expect(handleSubmit).toHaveBeenCalled();
+  });
+});
+```
+
+### 3.3 Hooks 测试
+
+```typescript
+import { renderHook, waitFor } from '@testing-library/react';
+import { useCardData } from './hooks';
+
+describe('useCardData', () => {
+  it('loads card data', async () => {
+    const { result } = renderHook(() => useCardData('test'));
+    
+    expect(result.current.loading).toBe(true);
+    
+    await waitFor(() => {
+      expect(result.current.loading).toBe(false);
+    });
+    
+    expect(result.current.data).toBeDefined();
+    expect(result.current.error).toBeNull();
+  });
+  
+  it('handles errors', async () => {
+    const { result } = renderHook(() => useCardData('invalid'));
+    
+    await waitFor(() => {
+      expect(result.current.loading).toBe(false);
+    });
+    
+    expect(result.current.error).toBeDefined();
+  });
+});
+```
+
+---
+
+**文档结束**

