+
+<script>
+const $ = s => document.querySelector(s);
+const $$ = s => [...document.querySelectorAll(s)];
+const api = async (p, q = {}) => {
+  const u = new URL(p, location.origin);
+  Object.entries(q).forEach(([k, v]) => { if (v !== "" && v != null) u.searchParams.set(k, v); });
+  const r = await fetch(u);
+  if (!r.ok) throw new Error((await r.json()).error || r.status);
+  return r.json();
+};
+
+// 状态颜色映射
+const STATUS_COLOR = {
+  "已覆盖": "#6ee7b7", "部分": "#e9a568", "缺失": "#f85149",
+  "冲突": "#a371f7", "已替代": "#6e7681", "已废弃": "#6e7681", "不适用": "#6e7681"
+};
+
+// 全局数据
+let allNodes = [];
+let allEdges = [];
+let allDimensions = [];
+let filteredNodes = [];
+let filteredEdges = [];
+let selectedNode = null;
+
+// 画布状态
+const canvas = $("#graphCanvas");
+const ctx = canvas.getContext("2d");
+let nodes = []; // { id, x, y, vx, vy, r, color, label, data }
+let edges = []; // { from, to, fromNode, toNode }
+let transform = { x: 0, y: 0, scale: 1 };
+let dragging = null;
+let hovering = null;
+
+// 初始化画布尺寸
+function resizeCanvas() {
+  const dpr = window.devicePixelRatio || 1;
+  const rect = canvas.getBoundingClientRect();
+  canvas.width = rect.width * dpr;
+  canvas.height = rect.height * dpr;
+  canvas.style.width = rect.width + "px";
+  canvas.style.height = rect.height + "px";
+  ctx.scale(dpr, dpr);
+  draw();
+}
+window.addEventListener("resize", resizeCanvas);
+
+// 加载数据
+async function loadData() {
+  try {
+    const [metaRes, graphRes] = await Promise.all([
+      api("/api/meta"),
+      api("/api/graph")
+    ]);
+    
+    $("#meta").textContent = `${graphRes.nodes.length} 节点 · ${graphRes.edges.length} 关系`;
+    
+    allNodes = graphRes.nodes.map(n => ({
+      ...n,
+      dimensions: Array.isArray(n.dimensions) ? n.dimensions : (n.dimensions || "").split(",").filter(Boolean)
+    }));
+    allEdges = graphRes.edges;
+    allDimensions = graphRes.dimensions || [];
+    
+    // 填充筛选器
+    $("#filterDim").innerHTML = "<option value=''>全部维度</option>" +
+      allDimensions.map(d => `<option value="${d}">${d}</option>`).join("");
+    $("#filterStatus").innerHTML = "<option value=''>全部状态</option>" +
+      graphRes.status_order.map(s => `<option value="${s}">${s}</option>`).join("");
+    $("#filterSource").innerHTML = "<option value=''>全部来源</option>" +
+      graphRes.sources.map(s => `<option value="${s}">${s}</option>`).join("");
+    
+    applyFilters();
+    buildTree();
+    $("#loading").classList.add("hide");
+  } catch (e) {
+    $("#loading").textContent = "加载失败：" + e.message;
+  }
+}
+
+// 应用筛选
+function applyFilters() {
+  const dim = $("#filterDim").value;
+  const status = $("#filterStatus").value;
+  const source = $("#filterSource").value;
+  const q = $("#searchBox").value.trim().toLowerCase();
+  
+  filteredNodes = allNodes.filter(n => {
+    if (dim && !n.dimensions.includes(dim)) return false;
+    if (status && n.status !== status) return false;
+    if (source && n.source_type !== source) return false;
+    if (q && !(n.id + n.topic).toLowerCase().includes(q)) return false;
+    return true;
+  });
+  
+  const nodeIds = new Set(filteredNodes.map(n => n.id));
+  filteredEdges = allEdges.filter(e => nodeIds.has(e.from_id) && nodeIds.has(e.to_id));
+  
+  $("#nodeCount").textContent = filteredNodes.length;
+  $("#edgeCount").textContent = filteredEdges.length;
+  
+  buildGraph();
+  buildTree();
+}
+
+// 构建力导向图
+function buildGraph() {
+  const w = canvas.getBoundingClientRect().width;
+  const h = canvas.getBoundingClientRect().height;
+  
+  nodes = filteredNodes.map((n, i) => ({
+    id: n.id,
+    x: w / 2 + (Math.random() - 0.5) * w * 0.6,
+    y: h / 2 + (Math.random() - 0.5) * h * 0.6,
+    vx: 0, vy: 0,
+    r: Math.max(8, 6 + (n.dimensions.length * 2.5)),
+    color: STATUS_COLOR[n.status] || "#6e7681",
+    label: n.topic || n.id,
+    data: n
+  }));
+  
+  const nodeMap = new Map(nodes.map(n => [n.id, n]));
+  edges = filteredEdges.map(e => ({
+    from: e.from_id,
+    to: e.to_id,
+    fromNode: nodeMap.get(e.from_id),
+    toNode: nodeMap.get(e.to_id),
+    relation: e.relation
+  })).filter(e => e.fromNode && e.toNode);
+  
+  transform = { x: 0, y: 0, scale: 1 };
+  startSimulation();
+}
+
+// 力导向布局模拟
+let simTimer = null;
+function startSimulation() {
+  if (simTimer) clearInterval(simTimer);
+  let iter = 0;
+  const maxIter = 400;
+  // 节点越多，理想边长和斥力越大，避免大图挤在一起
+  const n = nodes.length || 1;
+  const repelStrength = 2600 + Math.min(n * 12, 4000);
+  const idealEdgeLen = 90 + Math.min(n * 0.6, 160);
+
+  simTimer = setInterval(() => {
+    const settling = iter > maxIter;
+    iter++;
+    if (iter > maxIter + 40) { clearInterval(simTimer); fitToView(); return; }
+    
+    // 斥力
+    for (let i = 0; i < nodes.length; i++) {
+      for (let j = i + 1; j < nodes.length; j++) {
+        const dx = nodes[j].x - nodes[i].x;
+        const dy = nodes[j].y - nodes[i].y;
+        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
+        const force = repelStrength / (dist * dist);
+        const fx = (dx / dist) * force;
+        const fy = (dy / dist) * force;
+        nodes[i].vx -= fx; nodes[i].vy -= fy;
+        nodes[j].vx += fx; nodes[j].vy += fy;
+      }
+    }
+    
+    // 引力（边）
+    edges.forEach(e => {
+      const dx = e.toNode.x - e.fromNode.x;
+      const dy = e.toNode.y - e.fromNode.y;
+      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
+      const force = (dist - idealEdgeLen) * 0.06;
+      const fx = (dx / dist) * force;
+      const fy = (dy / dist) * force;
+      e.fromNode.vx += fx; e.fromNode.vy += fy;
+      e.toNode.vx -= fx; e.toNode.vy -= fy;
+    });
+    
+    // 中心引力（轻微，避免图谱飘散）
+    const cx = canvas.getBoundingClientRect().width / 2;
+    const cy = canvas.getBoundingClientRect().height / 2;
+    nodes.forEach(n => {
+      n.vx += (cx - n.x) * 0.0015;
+      n.vy += (cy - n.y) * 0.0015;
+    });
+    
+    // 更新位置
+    nodes.forEach(n => {
+      n.vx *= 0.88; n.vy *= 0.88;
+      n.x += n.vx; n.y += n.vy;
+    });
+    
+    if (!settling || iter % 3 === 0) draw();
+  }, 16);
+}
+
+// 自动缩放并居中，让全部节点都在可视范围内
+function fitToView() {
+  if (nodes.length === 0) return;
+  const pad = 80;
+  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
+  nodes.forEach(n => {
+    minX = Math.min(minX, n.x - n.r);
+    minY = Math.min(minY, n.y - n.r);
+    maxX = Math.max(maxX, n.x + n.r);
+    maxY = Math.max(maxY, n.y + n.r);
+  });
+  const w = canvas.getBoundingClientRect().width;
+  const h = canvas.getBoundingClientRect().height;
+  const contentW = Math.max(maxX - minX, 1);
+  const contentH = Math.max(maxY - minY, 1);
+  const scale = Math.min((w - pad * 2) / contentW, (h - pad * 2) / contentH, 2.5);
+  transform.scale = Math.max(scale, 0.05);
+  transform.x = w / 2 - ((minX + maxX) / 2) * transform.scale;
+  transform.y = h / 2 - ((minY + maxY) / 2) * transform.scale;
+  draw();
+}
+
+// 绘制
+function draw() {
+  const w = canvas.getBoundingClientRect().width;
+  const h = canvas.getBoundingClientRect().height;
+  ctx.clearRect(0, 0, w, h);
+  
+  ctx.save();
+  ctx.translate(transform.x, transform.y);
+  ctx.scale(transform.scale, transform.scale);
+  
+  // 计算相关节点集合
+  let relatedIds = new Set();
+  let relatedEdges = new Set();
+  if (selectedNode) {
+    relatedIds.add(selectedNode.id);
+    edges.forEach(e => {
+      if (e.fromNode.id === selectedNode.id || e.toNode.id === selectedNode.id) {
+        relatedIds.add(e.fromNode.id);
+        relatedIds.add(e.toNode.id);
+        relatedEdges.add(e);
+      }
+    });
+  }
+  
+  // 绘制边
+  edges.forEach(e => {
+    const isHighlight = selectedNode && relatedEdges.has(e);
+    ctx.strokeStyle = isHighlight ? "#38bdf8" : "#2a2f3a";
+    ctx.lineWidth = isHighlight ? 2.5 : 1.5;
+    ctx.globalAlpha = isHighlight ? 1 : (selectedNode ? 0.15 : 0.4);
+    ctx.beginPath();
+    ctx.moveTo(e.fromNode.x, e.fromNode.y);
+    ctx.lineTo(e.toNode.x, e.toNode.y);
+    ctx.stroke();
+  });
+  ctx.globalAlpha = 1;
+  
+  // 绘制节点
+  nodes.forEach(n => {
+    const isSelected = n === selectedNode;
+    const isRelated = selectedNode && relatedIds.has(n.id);
+    const isDimmed = selectedNode && !isRelated;
+    
+    ctx.globalAlpha = isDimmed ? 0.2 : 1;
+    ctx.fillStyle = n.color;
+    ctx.beginPath();
+    ctx.arc(n.x, n.y, n.r, 0, Math.PI * 2);
+    ctx.fill();
+    
+    if (isSelected || isRelated || n === hovering) {
+      ctx.strokeStyle = isSelected ? "#38bdf8" : (isRelated ? "#6ee7b7" : "#38bdf8");
+      ctx.lineWidth = isSelected ? 3 : 2;
+      ctx.stroke();
+    }
+    
+    // 绘制相关节点的标签
+    if (isRelated && selectedNode && n !== selectedNode) {
+      ctx.fillStyle = "#0f131c";
+      ctx.strokeStyle = "#2a2f3a";
+      ctx.lineWidth = 1;
+      const label = n.label.slice(0, 25);
+      ctx.font = "11px -apple-system, sans-serif";
+      const lw = ctx.measureText(label).width + 12;
+      ctx.fillRect(n.x + n.r + 6, n.y - 12, lw, 20);
+      ctx.strokeRect(n.x + n.r + 6, n.y - 12, lw, 20);
+      ctx.fillStyle = "#e6e9ef";
+      ctx.fillText(label, n.x + n.r + 12, n.y + 2);
+    }
+  });
+  ctx.globalAlpha = 1;
+  
+  // 绘制悬停标签
+  if (hovering && !selectedNode) {
+    ctx.fillStyle = "#0f131c";
+    ctx.strokeStyle = "#38bdf8";
+    ctx.lineWidth = 1;
+    const label = hovering.label.slice(0, 30);
+    ctx.font = "12px -apple-system, sans-serif";
+    const lw = ctx.measureText(label).width + 16;
+    ctx.fillRect(hovering.x + 10, hovering.y - 18, lw, 24);
+    ctx.strokeRect(hovering.x + 10, hovering.y - 18, lw, 24);
+    ctx.fillStyle = "#e6e9ef";
+    ctx.fillText(label, hovering.x + 18, hovering.y - 2);
+  }
+  
+  ctx.restore();
+}
+
+// 鼠标交互
+let mouseDown = false;
+let lastMouse = { x: 0, y: 0 };
+
+canvas.addEventListener("mousedown", e => {
+  mouseDown = true;
+  lastMouse = { x: e.clientX, y: e.clientY };
+  const [mx, my] = screenToWorld(e.clientX, e.clientY);
+  dragging = nodes.find(n => {
+    const dx = n.x - mx, dy = n.y - my;
+    return Math.sqrt(dx * dx + dy * dy) < n.r + 5;
+  });
+  if (dragging) {
+    selectedNode = dragging;
+    showDetail(dragging.data);
+  }
+});
+
+canvas.addEventListener("mousemove", e => {
+  if (mouseDown && dragging) {
+    const [mx, my] = screenToWorld(e.clientX, e.clientY);
+    dragging.x = mx;
+    dragging.y = my;
+    dragging.vx = 0;
+    dragging.vy = 0;
+    draw();
+  } else if (mouseDown) {
+    transform.x += e.clientX - lastMouse.x;
+    transform.y += e.clientY - lastMouse.y;
+    lastMouse = { x: e.clientX, y: e.clientY };
+    draw();
+  } else {
+    const [mx, my] = screenToWorld(e.clientX, e.clientY);
+    hovering = nodes.find(n => {
+      const dx = n.x - mx, dy = n.y - my;
+      return Math.sqrt(dx * dx + dy * dy) < n.r + 5;
+    });
+    draw();
+  }
+});
+
+canvas.addEventListener("mouseup", () => {
+  mouseDown = false;
+  dragging = null;
+});
+
+canvas.addEventListener("wheel", e => {
+  e.preventDefault();
+  const delta = e.deltaY > 0 ? 0.9 : 1.1;
+  const [mx, my] = screenToWorld(e.clientX, e.clientY);
+  transform.scale *= delta;
+  transform.x = e.clientX - (mx * transform.scale);
+  transform.y = e.clientY - (my * transform.scale);
+  draw();
+});
