#!/usr/bin/env python3
"""补全拆分空壳：从母文档回填被拆分工具清空的章节文件。

拆分命名约定：<分区号>.<序号>-<母文档名>-<章节标题>.md，母文档为去掉数字前缀的文件。
仅处理"空壳"文件（正文不足 3 行有效内容且含"文档结束"）。
"""

import os
import re

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
LIB = os.path.abspath(os.path.join(BASE, "..", "..", "薯片生态文档库"))
SHELL_RE = re.compile(r"^(\d+)\.(\d+)-(.+?)-(第[一二三四五六七八九十]+|[一二三四五六七八九十]+、.+|\d+(?:\.\d+)*\s*.+|相关文档)\.md$")


def section_of(hub_text, title):
    """在母文档中找标题（h1-h4 任意），返回从该标题到下一个同级或更高级标题之间的文本。"""
    lines = hub_text.splitlines(keepends=True)
    target = None
    for i, line in enumerate(lines):
        m = re.match(r"^(#{1,4})\s+(.*?)\s*$", line.rstrip("\n"))
        if m and title.strip() in m.group(2):
            target = (i, len(m.group(1)))
            break
    if target is None:
        return None
    start, level = target
    out = [lines[start]]
    for line in lines[start + 1:]:
        m = re.match(r"^(#{1,6})\s+", line)
        if m and len(m.group(1)) <= level:
            break
        out.append(line)
    return "".join(out).strip("\n")


def header_of(hub_text):
    lines = hub_text.splitlines(keepends=True)
    out = []
    for line in lines:
        if line.startswith("# "):
            out.append(line)
            continue
        if out and (line.startswith("## ") or line.startswith("### ")):
            break
        if out:
            out.append(line)
    return "".join(out).strip("\n")


def is_shell(text):
    body = [l for l in text.splitlines() if l.strip() and not l.startswith(("#", ">", "**", "---"))]
    return len(body) <= 2


def main():
    fixed = []
    for root, _dirs, files in os.walk(LIB):
        for name in files:
            if not name.endswith(".md"):
                continue
            m = SHELL_RE.match(name)
            if not m:
                continue
            path = os.path.join(root, name)
            with open(path, encoding="utf-8") as f:
                shell = f.read()
            if not is_shell(shell):
                continue
            hub_name = f"{m.group(3)}.md"
            hub_path = os.path.join(root, hub_name)
            if not os.path.exists(hub_path):
                continue
            with open(hub_path, encoding="utf-8") as f:
                hub = f.read()
            section = section_of(hub, m.group(4))
            if not section:
                continue
            new = f"{header_of(hub)}\n\n---\n\n{section}\n\n---\n\n**文档结束**\n"
            if len(new) > len(shell):
                with open(path, "w", encoding="utf-8") as f:
                    f.write(new)
                fixed.append(name)
    print(f"回填空壳 {len(fixed)} 个：")
    for name in fixed:
        print("  ", name)


if __name__ == "__main__":
    main()

