   const afterScheme = input.slice(separatorIndex + 2);
   const authorityEnd = afterScheme.indexOf('/');
   if (authorityEnd < 0) {
     throw invalidUri('absolute', '资源地址缺少作用域路径');
   }
   return {
     authority: afterScheme.slice(0, authorityEnd),
     raw: afterScheme.slice(authorityEnd + 1),
   };
