             request.id.clone(),
             PluginRecord {
                 version: request.version,
                 available_versions: request.available_versions,
                 dependencies: request.dependencies,
                 role: request.role,
                 parent: request.parent,
                 state: PluginState::Installed,
                 context: None,
                 fork: None,
                 last_error: None,
                 last_failure: None,
                 runner: request.runner,
                 cancel_requested: false,
