     pub(crate) fn mark(&mut self, id: &str, next: PluginState) -> Result<(), KernelError> {
         let record = self
             .records
             .get_mut(id)
             .ok_or_else(|| KernelError::PluginNotFound { id: id.to_owned() })?;
         if !record.state.can_transition_to(next) {
