 use chips_core::{CORE_ABI_VERSION, PLATFORM_VERSION};
 use neon::prelude::*;

 /// 生成导出名表与集中注册函数。
 macro_rules! export_table {
     ($( $name:literal => $function:path ),* $(,)?) => {
         /// ABI 导出名表；顺序与注册顺序一致。
         ///
         /// 事实源：本表、`abi/export-surface.json`、`types/chips-native.d.ts`
