     match result {
         Ok(value) => match value.downcast::<JsServiceValue>() {
             Ok(service) => Ok(ServiceLookup::Js(service)),
             Err(_) => Ok(ServiceLookup::NonJs),
         },
         Err(KernelError::ServiceNotFound { .. }) => Ok(ServiceLookup::Missing),
