     if let Ok(buffer) = value.downcast::<JsBuffer, _>(cx) {
         let mut bytes = Vec::new();
         bytes.extend_from_slice(buffer.as_slice(cx));
         return Some(bytes);
     }
     if let Ok(array) = value.downcast::<JsUint8Array, _>(cx) {
         let mut bytes = Vec::new();
         bytes.extend_from_slice(array.as_slice(cx));
         return Some(bytes);
     }
     None
 }

